var rows = JSON.parse(value);
var seen = {};
var result = [];
rows.forEach(function(row) {
    var id = row.labels.vpc_id;
    var key = '$' + id;
    if (id && !seen[key]) {
        seen[key] = true;
        result.push({labels: {vpc_id: id}});
    }
});
return JSON.stringify(result);
